-- 2. Multi-value answers (checkbox), mapped part by part and rejoined in the stored order.
--    A part that matches no label is kept as it is: an off-list answer stays visible as itself.
with map(question_id, label, value) as (values
    ('env_reporting', 'CDP', 'cdp'),
    ('env_reporting', 'GRI', 'gri'),
    ('env_reporting', 'ESRS/CSRD', 'esrs_csrd'),
    ('env_reporting', 'EcoVadis', 'ecovadis'),
    ('env_reporting', 'Other', 'other'),
    ('env_reporting', 'None', 'none')
), rewritten as (
  select r.id,
         string_agg(coalesce(m.value, p.part), ', ' order by p.ord) as response
    from supplier_responses r
    cross join lateral unnest(string_to_array(r.response, ',')) with ordinality as p(part, ord)
    left join map m on m.question_id = r.question_id and m.label = btrim(p.part)
   where r.question_id in ('env_reporting')
     and r.response is not null
   group by r.id
)
update supplier_responses r
   set response = w.response, updated_at = now()
  from rewritten w
 where r.id = w.id and r.response <> w.response;

commit;
